let S=Table.DuplicateColumn(query,"Date","Original"), T=Table.TransformColumnTypes(S,{{"Date",type date}},"en-US"), A=Table.AddColumn(T,"Check",each let V=try [Date] in [HasError=V[HasError],ISO=if V[HasError] or V[Value]=null then null else Date.ToText(V[Value],"yyyy-MM-dd","en-US"),Message=if V[HasError] then V[Error][Message] else null]), R=Table.RemoveColumns(A,{"Date"}) in Table.ExpandRecordColumn(R,"Check",{"HasError","ISO","Message"})
